from gklib import L, S, Q
L("careers","jobs-that-keep-a-town-running","5-7","Jobs That Keep a Town Running","Meet the helpers around us: doctors, farmers, drivers, teachers and more.","👩‍🔧",[
 S("Helpers everywhere","Many people work to keep our town running. | Farmers grow our food, bakers make bread and shopkeepers sell what we need. | Each job is useful and each worker deserves respect.",["Many helpers","Every job matters"]),
 S("Health and safety","Doctors and nurses help us when we are ill. | Firefighters put out fires and police keep people safe. | Sanitation workers keep our streets clean, which keeps us healthy.",["Doctors and nurses","Firefighters and police","Cleaners"]),
 S("Learning and building","Teachers help us learn, and librarians help us find books. | Engineers and masons build roads, bridges and houses. | Electricians and plumbers fix the lights and the water.",["Teachers","Builders","Electricians and plumbers"]),
 S("What will you be?","Some jobs are old, and some are brand new, like drone pilots and app makers. | Think about what you enjoy and what you are good at. | You can also change your mind many times as you grow.",["Find what you enjoy","You can change your mind"]),
],facts=["A single bridge needs many different workers, from designers to welders.","Postal workers in India deliver letters to even remote villages.","Farmers in India feed more than a billion people."],
quiz=[Q("Who helps us when we are ill?",["Doctors and nurses","Bakers","Drivers"],0,"Doctors and nurses care for the sick."),
Q("Who builds roads and bridges?",["Engineers and builders","Singers","Librarians"],0,"Engineers and builders make them."),
Q("Whose job helps us find books?",["Librarian","Pilot","Farmer"],0,"A librarian helps you find books.")],tags=["jobs","community"])

L("careers","how-to-choose-what-to-study","14+","How to Choose What to Study","A practical way to think about subjects, strengths and careers without panic.","🧭",[
 S("Start with three questions","Ask what you enjoy doing, what you are good at, and what the world needs. | Where these overlap is a good place to look. | You do not need a final answer now.",["Enjoy","Good at","Needed"]),
 S("Know the fields","Broadly, fields include science and technology, medicine and health, commerce and business, law and public service, arts and design, and skilled trades. | Each has many different jobs inside it. | For example, a person in science might become a researcher, a teacher or a data analyst.",["Many fields","Many jobs in each"]),
 S("Try before you decide","Join clubs, do small projects, talk to people who do the work and watch good online lectures. | Even a short try tells you if you like the daily reality of a job. | Notice what you lose track of time doing.",["Try small projects","Talk to people","Notice what absorbs you"]),
 S("Keep doors open","Strong basics in maths, reading, writing and clear thinking help in almost every career. | Skills like teamwork and learning new things are valuable everywhere. | Many people change careers, so choose for now and keep learning.",["Basics help everywhere","Careers can change"]),
],facts=["Many of today's jobs did not exist twenty years ago, such as social media manager and app developer.","Entrance exams and course options in India change from time to time, so check official sources for the latest rules.","Skilled trades like electrician and chef offer good careers too."],
quiz=[Q("Which question helps choose a field?",["What do I enjoy and do well?","What is my friend choosing?","What is easiest?"],0,"Interests and strengths are a good start."),
Q("Why try small projects?",["To learn what the work is really like","To waste time","To avoid decisions"],0,"Trying shows the daily reality of a field."),
Q("Which skills help in almost every career?",["Reading, writing, maths and clear thinking","Only memorising","None"],0,"Strong basics open many doors.")],tags=["career","study"],asof="November 2026",notes="Exam and admission rules change; confirm with official sources.")

L("inventors","inventions-that-changed-the-world","8-10","Inventions That Changed the World","The wheel, fire, the printing press, electricity and the telephone, and why they mattered.","💡",[
 S("The wheel","The wheel was invented more than five thousand years ago, first used by potters and then for carts. | It made it easier to carry heavy loads and travel far. | Today wheels are in cars, trains, machines and even clocks.",["About 5,000 years ago","Carry loads"]),
 S("Printing","Before printing, books were copied by hand, so they were costly and rare. | In the 1400s Johannes Gutenberg in Europe made printing with movable metal type practical. | Books became cheaper and ideas spread faster.",["Gutenberg","Cheaper books"]),
 S("Electricity and light","In the 1800s scientists such as Michael Faraday learned how to make electricity. | Inventors such as Thomas Edison and Joseph Swan helped make practical electric lights. | Light, factories, fans and phones all depend on electricity today.",["Faraday","Electric light"]),
 S("Talking across distance","Alexander Graham Bell was awarded a patent for the telephone in 1876. | Later came radio, television and mobile phones. | Now we can talk to a person anywhere in the world in a moment.",["Telephone 1876","Mobile phones today"]),
],facts=["Many inventions were built on earlier ideas by many people, not by one person alone.","Paper was invented in China around two thousand years ago.","India's Aryabhata and other scholars gave the world important ideas in maths and astronomy."],
quiz=[Q("What did Gutenberg make practical in Europe?",["Printing with movable type","The telephone","Paper"],0,"Gutenberg's printing press used movable metal type."),
Q("Who received the telephone patent in 1876?",["Alexander Graham Bell","Michael Faraday","Thomas Edison"],0,"Bell was awarded the patent in 1876."),
Q("About how old is the wheel?",["More than 5,000 years","About 100 years","About 500 years"],0,"The wheel is over five thousand years old.")],tags=["inventions","history"],notes="Invention credits are simplified; many people contributed to each.")

L("inventors","great-indian-scientists","11-13","Great Indian Scientists","C. V. Raman, Srinivasa Ramanujan, Jagadish Chandra Bose, A. P. J. Abdul Kalam and Kalpana Chawla.","🔭",[
 S("C. V. Raman","Chandrasekhara Venkata Raman, born in Tiruchirappalli in Tamil Nadu, studied how light scatters in materials. | His discovery, the Raman effect, was announced in 1928. | He won the Nobel Prize in Physics in 1930, and India celebrates National Science Day on 28 February to mark it.",["Raman effect","Nobel Prize 1930","National Science Day"]),
 S("Srinivasa Ramanujan","Srinivasa Ramanujan, born in Erode, was a self-taught mathematician who loved numbers. | He sent his work to the mathematician G. H. Hardy in England and was invited to Cambridge. | He found thousands of results before dying young at 32.",["Born in Erode","Self-taught genius"]),
 S("J. C. Bose and Kalam","Jagadish Chandra Bose showed that plants respond to stimuli and built sensitive instruments. | A. P. J. Abdul Kalam, from Rameswaram, helped develop India's rockets and became India's President from 2002 to 2007. | He loved teaching young people and writing books.",["Bose: plants and instruments","Kalam: rockets and teaching"]),
 S("Kalpana Chawla","Kalpana Chawla, born in Karnal, Haryana, became the first woman of Indian origin to go to space. | She flew on the Space Shuttle Columbia in 1997 and 2003. | She lost her life in the Columbia accident in 2003 and inspires many young learners.",["First Indian-born woman in space","Columbia mission"]),
],facts=["Ramanujan's number 1729 is called the Hardy-Ramanujan number, the smallest number that is a sum of two cubes in two different ways.","National Science Day in India is celebrated on 28 February.","Kalam was nicknamed the Missile Man of India."],
quiz=[Q("What is the Raman effect about?",["Scattering of light","Sound waves","Magnets"],0,"It concerns how light scatters."),
Q("Where was Ramanujan born?",["Erode","Mumbai","Delhi"],0,"He was born in Erode, Tamil Nadu."),
Q("Who was the first woman of Indian origin in space?",["Kalpana Chawla","Indira Gandhi","Sunita Rao"],0,"Kalpana Chawla flew in 1997.")],tags=["scientists","india"],notes="Dates from standard biographies. Kalpana Chawla was born in Karnal; she was an American citizen of Indian origin.")

L("ideas","what-is-democracy","11-13","What Is Democracy?","Voting, rights, rules and why many countries choose their leaders.","🗳️",[
 S("Rule by the people","In a democracy, people choose their leaders by voting. | The word comes from Greek: demos means people and kratos means rule. | India is the world's largest democracy by number of voters.",["People choose leaders","Greek roots"]),
 S("Rights and duties","Citizens have rights, such as freedom of speech and equality before the law. | They also have duties, such as obeying laws and protecting public property. | The Indian Constitution lists both.",["Rights","Duties"]),
 S("How voting works","In India, citizens aged 18 and above can vote. | Elections are run by the Election Commission of India, and Electronic Voting Machines record votes. | The vote is secret, so no one can force you to choose.",["Age 18","Election Commission","Secret vote"]),
 S("Why it matters","A democracy lets people change leaders peacefully and speak about problems. | Free news, courts and citizens who ask questions help keep it healthy. | Learning to listen to different views is the first step of democracy.",["Peaceful change","Listen to others"]),
],facts=["Athens in ancient Greece had an early form of democracy, but only some people could vote.","India held its first general election in 1951-52.","The voting age in India was lowered from 21 to 18 in 1989."],
quiz=[Q("At what age can Indian citizens vote?",["18","21","16"],0,"The voting age is 18."),
Q("What does the word democracy come from?",["Greek","Latin only","Tamil only"],0,"It comes from Greek words meaning people and rule."),
Q("Who runs elections in India?",["Election Commission of India","The army","Schools"],0,"The Election Commission conducts elections.")],tags=["democracy","civics"],notes="Neutral civics explanation; no party or leader is discussed.")

L("ideas","time-zones-and-the-calendar","8-10","Time Zones and the Calendar","Why it is morning in India while it is night in America, and how calendars work.","🕰️",[
 S("Earth turns","The Earth spins once in about 24 hours. | At any moment half the world faces the Sun and has daytime, and the other half has night. | That is why people far apart have different times.",["Earth spins","Day and night"],"clock-time"),
 S("Time zones","The world is divided into time zones, roughly 15 degrees of longitude wide, one hour apart. | India uses one time zone for the whole country, Indian Standard Time, which is 5 hours and 30 minutes ahead of Universal Time. | Some big countries, like the United States, use several.",["One hour per zone","India: IST, UTC+5:30"],"clock-time"),
 S("The calendar","A year is the time Earth takes to go once around the Sun, about 365 and a quarter days. | We add an extra day, 29 February, every four years in a leap year to keep up. | A week of seven days and a month come from old ideas about the Moon and planets.",["365 and a quarter days","Leap years"]),
 S("Many calendars","Different cultures also use other calendars, such as the Tamil calendar with Chithirai as its first month, and the Hindu, Islamic and Chinese calendars. | Many are based on the Moon or the Sun. | That is why some festivals fall on different dates each year in the common calendar.",["Many calendars","Moon and Sun"]),
],facts=["Nepal's time is 5 hours 45 minutes ahead of UTC, a rare 45 minute offset.","The International Date Line is where the date changes as you cross the Pacific Ocean.","Tamil New Year usually falls in mid April."],
quiz=[Q("How many hours does the Earth take to spin once?",["About 24","About 12","About 365"],0,"It takes about 24 hours."),
Q("What is India's time zone called?",["Indian Standard Time","Delhi Time","Madras Time only"],0,"Indian Standard Time is used all over India."),
Q("How often is there a leap year?",["Every four years","Every year","Every ten years"],0,"Typically every four years.")],tags=["time","calendar"])
